CREATE COLUMN TABLE "TEST_AP"."TRN1" ("TrnAbsEntr" INTEGER CS_INT NOT NULL , "LineNum" INTEGER CS_INT NOT NULL , "ItemCode" NVARCHAR(254) NOT NULL , "ItemType" NVARCHAR(8) NOT NULL , "SlimType" NVARCHAR(8), "MaxLength" INTEGER CS_INT, "SourceText" NCLOB MEMORY THRESHOLD 1000, "Memo" NCLOB MEMORY THRESHOLD 1000, PRIMARY KEY ("TrnAbsEntr", "LineNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "TRN1_UniqueIdx" ON "TEST_AP"."TRN1" ( "TrnAbsEntr" ASC, "ItemType" ASC, "ItemCode" ASC, "LineNum" ASC )